<template><div class="checkout"><div class="address" @click="selectAddress"><el-icon><Location/></el-icon><div class="info" v-if="address"><div>{{ address.name }} {{ address.phone }}</div><div>{{ address.detail }}</div></div><div class="info" v-else><div>请选择收货地址</div></div><el-icon><ArrowRight/></el-icon></div><div class="goods-list"><div v-for="item in cartItems" :key="item.id" class="goods-item"><el-image :src="item.image" fit="cover" style="width:60px;height:60px"/><div class="info"><div class="name">{{ item.name }}</div><div class="spec">{{ item.spec }}</div><div class="bottom"><span class="price">¥{{ item.price }}</span><span class="qty">x{{ item.quantity }}</span></div></div></div></div><div class="amount"><div class="row"><span>商品总额</span><span>¥{{ totalAmount }}</span></div><div class="row"><span>运费</span><span>¥0</span></div><div class="row total"><span>实付</span><span class="price">¥{{ totalAmount }}</span></div></div><div class="footer"><el-button type="primary" @click="submitOrder" :loading="loading">提交订单</el-button></div></div></template><script setup>import{ref,computed,onMounted}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import request from'@/utils/request';const router=useRouter();const address=ref(null);const cartItems=ref([]);const loading=ref(false);const totalAmount=computed(()=>cartItems.value.reduce((sum,item)=>sum+item.price*item.quantity,0).toFixed(2));const selectAddress=()=>router.push('/address');const submitOrder=async()=>{if(!address.value){ElMessage.warning('请选择收货地址');return}loading.value=true;try{const res=await request({url:'/orders',method:'post',data:{address_id:address.value.id,items:cartItems.value.map(i=>({goods_id:i.goods_id,spec:i.spec,quantity:i.quantity,price:i.price}))}});ElMessage.success('下单成功');router.push('/pay/'+res.data.order_no)}catch(e){ElMessage.error('下单失败')}finally{loading.value=false}};onMounted(async()=>{const addrRes=await request({url:'/addresses'});if(addrRes.data&&addrRes.data.length)address.value=addrRes.data[0];const cartRes=await request({url:'/cart'});cartItems.value=cartRes.data?.list||cartRes.data||[]})</script><style scoped>.checkout{padding-bottom:70px}.address{display:flex;align-items:center;padding:15px;background:#fff;margin:10px;border-radius:8px}.address .info{flex:1;margin-left:10px;font-size:14px}.goods-list{background:#fff;margin:10px;border-radius:8px;padding:10px}.goods-item{display:flex;padding:10px 0;border-bottom:1px solid #f5f5f5}.goods-item .info{margin-left:10px;flex:1}.goods-item .name{font-size:14px}.goods-item .spec{font-size:12px;color:#909399;margin:3px 0}.goods-item .bottom{display:flex;justify-content:space-between;margin-top:5px}.goods-item .price{color:#f56c6c}.amount{background:#fff;margin:10px;padding:15px;border-radius:8px}.amount .row{display:flex;justify-content:space-between;padding:5px 0;font-size:14px}.amount .total{border-top:1px solid #eee;margin-top:10px;padding-top:10px;font-weight:bold}.amount .price{color:#f56c6c;font-size:18px}.footer{position:fixed;bottom:0;left:0;right:0;padding:10px 20px;background:#fff;border-top:1px solid #eee;display:flex;justify-content:flex-end}</style>
